item.aggregated_output:
		\hat{M}^{(\mathrm{Point},X),x}_a \, \hat{M}^{(\mathrm{Point},Z),z}_b .
	\]
	Then $\{R^{x,z}_{a,b}\}_{a,b \in \F_q}$ is a POVM; on every placement,
	on average over $x, z$,
	$R^{x,z}_{a,b} \approx_{\delta_{\mathrm{Anticom}}}
	\hat{M}^{(\mathrm{Point},Z),z}_b \hat{M}^{(\mathrm{Point},X),x}_a$; and
	for every pair of opposite placements the ordered product on the first
	is $\eps$-close to the reversed ordered product on the second.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:qld-point-commutation-field, lem:qld-comm-cons, fact:add-a-proj}
	$R^{x,z}_{a,b} = (\hat{M}^X_a \hat{M}^Z_b)^\dagger (\hat{M}^X_a \hat{M}^Z_b)$
	is positive and $\sum_{a,b} R^{x,z}_{a,b} = \sum_b \hat{M}^Z_b = \Id$.
	Since $R^{x,z}_{a,b} - \hat{M}^Z_b \hat{M}^X_a
	= \hat{M}^Z_b [\hat{M}^X_a, \hat{M}^Z_b]$ and $\hat{M}^Z_b$ is a
	contraction, Lemma~\ref{lem:qld-point-commutation-field} gives the
	closeness. For the cross-placement consistency, the two factors are
	transported one at a time: $\hat{M}^Z_b$ on the first placement times the
	difference of the two placements of $\hat{M}^X_a$, then $\hat{M}^X_a$ on
	the second placement times the difference of the two placements of
	$\hat{M}^Z_b$; each is controlled by item~1 of
	Lemma~\ref{lem:qld-comm-cons} through Lemma~\ref{fact:add-a-proj}, and
	the two estimates combine by the triangle inequality.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:qld-4-10}: consistency of the sandwich]
	\label{lem:qld-sandwich-consistency}
	\lean{MIPStarRE.QPBT.sandwich_overlap_identity}
	\lean{MIPStarRE.QPBT.sandwich_defect_pointwise_le}
	\lean{MIPStarRE.QPBT.ProjectiveSetting.sandwichDefectBound}
	\lean{MIPStarRE.QPBT.ProjectiveSetting.sandwich_offDiagonal_le_sandwichDefectBound}
	\lean{MIPStarRE.QPBT.ProjectiveSetting.avg_sandwichDefectBound_le}
	\leanok
	\uses{lem:qld-sandwich, lem:qld-placement-transfer, def:consistency,
		fact:agreement, lem:qld-comm-cons, lem:qld-point-commutation-field}
	This formalization-only auxiliary is not a named statement of the paper;
	it replaces the Cauchy--Schwarz chain of displays
	\eqref{eq:qld-rw-self-cons-1}--\eqref{eq:qld-rw-self-cons-4} of the
	source by an exact identity. Let $P_1, P_2$ denote the two placements of an
	operator $P$ on a pair of opposite register pairs, let
	$W_b = (\hat{M}^Z_b)_1 (\hat{M}^Z_b)_2$, and let
	$D^W_c = (\hat{M}^W_c)_1 - (\hat{M}^W_c)_2$. Then, for fixed $(x,z)$,
	\[
		\sum_{(a,b) \ne (a',b')} \bra{\hat\psi} (R^{x,z}_{a,b})_1
		(R^{x,z}_{a',b'})_2 \ket{\hat\psi}
		= \tfrac12 \sum_b \lVert D^Z_b \ket{\hat\psi} \rVert^2
		+ \tfrac12 \sum_{a,b} \lVert D^X_a W_b \ket{\hat\psi} \rVert^2 ,
	\]
	and the right-hand side is at most
	$c_{x,z} = \tfrac12 \sum_b \lVert D^Z_b \hat\psi \rVert^2
	+ \tfrac32 \big( \sum_a \lVert D^X_a \hat\psi \rVert^2 + K_1 + K_2 \big)$,
	where $K_i = \sum_{a,b} \lVert ([\hat{M}^X_a, \hat{M}^Z_b])_i
	\hat\psi \rVert^2$. On average over $x, z$,
	$c_{x,z} \le C (\eps + \sqrt{\eps})$ for a universal constant $C$.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:qld-sandwich, fact:agreement, lem:qld-comm-cons,
		lem:qld-point-commutation-field}
	The placements commute and the effects are Hermitian projectors, so
	$\bra{\hat\psi} (R_{a,b})_1 (R_{a,b})_2 \ket{\hat\psi}
	= \bra{W_b \hat\psi} (\hat{M}^X_a)_1 (\hat{M}^X_a)_2 \ket{W_b \hat\psi}$,
	and the identity
	$\sum_c \bra{w} P_c Q_c \ket{w} = \lVert w \rVert^2
	- \tfrac12 \sum_c \lVert (P_c - Q_c) w \rVert^2$ for projective
	measurements, applied once with $w = W_b \hat\psi$ and once with
	$w = \hat\psi$, gives the displayed identity. Writing
	$D^X_a W_b = W_b D^X_a + (\hat{M}^Z_b)_2 ([\hat{M}^X_a, \hat{M}^Z_b])_1
	- (\hat{M}^Z_b)_1 ([\hat{M}^X_a, \hat{M}^Z_b])_2$ and using that the
	$\hat{M}^Z_b$ are contractions whose squares sum to the identity gives the
	bound; its average is controlled by item~1 of
	Lemma~\ref{lem:qld-comm-cons} and Lemma~\ref{lem:qld-point-commutation-field}.
\end{proof}

