1279	\subsection{Statement of results}
1280	\label{sec:twoplayer}
1281	
1282	We state the analysis of the Pauli braiding test in two parts: first
1283	we show that success in the test implies that observables~\eqref{eq:hatx-def} constructed from Alice and Bob's measurement operators approximately obey certain relations; then we show that these relations imply the existence of a local isometry under which the operators are close to operators satisfying the relations exactly.  
1284	
1285	\begin{theorem}  \label{thm:gametwoplayer}
1286	 Suppose a strategy $(N,\ket{\psi}_{AB})$ succeeds in the
1287	  Pauli braiding test (Figure~\ref{fig:protocol2player}) with probability at least
1288	  $\omega^*_{\enc} - \eps$, when the game $G_\ac$ is an $(\wg,\delta)$ anticommutation game. Then the following approximate relations hold, where operators $W^D$ are defined in~\eqref{eq:hatx-def} for $W\in\{X,Z\}$ and $D\in\{A,B\}$ and $\rho=\proj{\psi}$. 
1289		\begin{enumerate}
1290	\item (Approximate consistency) For $W \in \{X, Z\}$, $\E_{a}
1291	  \Drho(W^A(a), W^B(a))^2 = O(\eps)$;
1292	\item (Approximate linearity) For $W \in \{X, Z\}$, $\E_{a,b} \Drho
1293	  (W^A(a) W^A(b), W^A(a+b) )^2 = O(\sqrt{\eps})$;
1294	\item (Approximate anticommutation) $\E_{a, b|a\cdot b=1} \Drho( X^A(a) Z^A(b) ,
1295	  - Z^A(b) X^A(a))^{2} = O(\delta(\eps))$;
1296	\item (Approximate commutation) $\E_{a, b|a\cdot b=0} \Drho( X^A(a) Z^A(b) ,
1297	  Z^A(b) X^A(a))^{2} = O(\eps^{1/4} + \delta(\eps)^{1/2})$. 
1298	\end{enumerate}
1299	\end{theorem}
1300	
1301	We note that the constant $\omega^*_{\enc}$ is given by
1302	\begin{equation} \omega^*_{\enc} = \frac{2}{3} + \frac{1}{3}
1303	  \wg, \label{eq:omegaenc} \end{equation}
1304	where $\wg \in (0, 1]$ is the winning parameter associated with the $(\wg,\delta)$ anticommutation game $G_\ac$ used in the protocol. Thus if $\wg=1$ then $\omega^*_{\enc}=1$ as well. 
1305	
1306	
1307	\begin{theorem}
1308	\label{thm:isotwoplayer}
1309	Suppose given a bipartite state $\ket{\psi}_{AB}\in\mH_A\otimes\mH_B$, and
1310	observables $\{X^A(a)\}_{a\in\{0,1\}^n}$, $\{Z^A(b)\}_{b\in\{0,1\}^n}$ on $\mH_A$ and
1311	$\{X^B(a)\}_{a\in\{0,1\}^n}, \{Z^B(b)\}_{b\in\{0,1\}^n}$ on $\mH_B$ such that conditions 1.,2. and 3. in Theorem~\ref{thm:gametwoplayer} are satisfied, for some $\eps>0$ and $\delta(\eps)=O(\sqrt{\eps})$.\footnote{The restriction on $\delta$ is not necessary, but it is satisfied for both the CHSH and Magic Square games, and simplifies the presentation.} 
1312	Then there exists a state 
1313	$$\ket{\Psi}_{AB} = \ket{\psi}_{AB} \ot \ket{\EPR}_{A'A''} \ot \ket{\EPR}_{B'B''}\in \big(\mH_A \otimes (\C^2_{A'}\otimes \C^2_{A''})^{\otimes n} \big) \otimes \big(\mH_B \otimes (\C^2_{B'}\otimes \C^2_{B''})^{\otimes n} \big)$$
1314	 and
