1376	\subsubsection{Consistency Test}
1377	
1378	
1379	The following lemma states consequences of the consistency test we will use. 
1380	
1381	\begin{lemma}\label{lem:consistency}
1382	Suppose the strategy $(N,\ket{\psi})$ succeeds in the consistency test with probability $1-\eps$. Then there exists $\eps_{\stab} = O(\eps)$ such that 
1383	\[ \E_a \DIS_{\rho}(X^A(a), {X^B}(a) )^2  \leq \eps_{stab} \qquad \text{and} \qquad  \E_b \DIS_\rho({Z^A}(b), {Z^B}(b))^2 \leq \eps_{stab},\]
1384	and
1385	\[ \E_{a,b|a\cdot b=1} \DIS_{\rho}({{X}^A}(a), {{X'}^B}(a,b) )^2  \leq \eps_{stab} \qquad \text{and} \qquad  \E_{a,b|a\cdot b=1} \DIS_\rho({{Z}^A}(b), {{Z'}^B}(a,b))^2 \leq \eps_{stab}. \]
1386	Moreover, the honest strategy succeeds in the test with probability
1387	$1$. 
1388	\end{lemma}
1389	
1390	\begin{proof}
1391	It follows from the definition of $\CON_\rho$ that any strategy $(N,\ket{\psi})$ succeeding in the test with probability $1 - \eps$ satisfies 
1392	 \begin{align*}
1393	 \frac{1}{2}\Big( \E_{a,b|a\cdot b=1} \CON_\rho({X}^A(a), {{X'}^B}(a,b)) + \E_{a} \CON_\rho({X}^A(a), {{X}^B}(a))\Big)\,  &= 1 - O(\eps) \\
1394	\frac{1}{2}\Big(   \E_{a,b|a\cdot b=1} \CON_\rho({Z}^A(b), {{Z'}^B}(a,b))+ \E_{b} \CON_\rho({{Z}^A}(b), {{Z}^B}(b))\Big) &= 1 - O(\eps).
1395	 \end{align*}
1396	The first part of the lemma follows directly by applying \myeqref{condist} to the above relations. The second part follows from the definition of the honest strategy and the fact that 
1397	$$\sigma_X \otimes \sigma_X \ket{\EPR} = \sigma_Z \otimes \sigma_Z \ket{\EPR} = \ket{\EPR}.$$ 
