1399	%$$\E_{a} \DIS_\rho(X^A(a), {{X'}^B}(a))^2 = O(\eps)\qquad \text{and}\qquad \E_{b} \DIS_\rho({Z^A}(b), {{Z'}^B}(b))^2 = O(\eps).$$
