1541	\[ P^A(a, b) := D(a, b) \ot \sigx(a)_{A''} \sigz(b)_{A''}. \]
1542	We claim that $P^A(a,b)$ satisfies the desired properties.
1543	\begin{enumerate}
1544	\item[(b)] Pauli braiding: This follows from linearity of $D(a,b)$:
1545	  \begin{align*}
1546	    P^A(a,b) P^A(a',b') &= D(a,b)D(a',b') \ot \sigx(a)_{A''}
1547	                            \sigz(b)_{A''}
1548	                            \sigx(a')_{A''}\sigz(b')_{A''} \\
1549	                          &= D(a+a', b+b') \ot (-1)^{a' \cdot b}
1550	                            \sigx(a + a')_{A''} \sigz(b + b')_{A''} \\
1551	                          &= (-1)^{a' \cdot b} P^A(a+a', b+b') .
1552	  \end{align*}
1553	\item[(a)] Approximate consistency: We establish this in two steps. First,
1554	  note that $D(a, b)$ is approximately consistent with $C(a, b)$, so 
1555	\begin{align*}
1556	   P^A_{a,b} \ket{\Psi} &=^{a,b} D(a,b) \ot \sigx(a)_{A''}
1557	  \sigz(b)_{A''} \ket{\Psi}\\
1558	  &\app{\eps^{1/8}}{a,b} C(a, b) \ot \sigx(a)_{A''}
1559	  \sigz(b)_{A''} \ket{\Psi}\\
1560	  &\app{\eps^{1/4}}{a,b} X^A(a)Z^A(b) \ot \sigx(a)_{A'} \sigz(b)_{A'} \ot \sigx(a)_{A''}
1561	    \sigz(b)_{A''}\ket{\Psi} \\
1562	  &=^{a,b} X^A(a)Z^A(b) \ot \Id_{A' A''} \ket{\Psi},
1563	\end{align*}
1564	where the last line follows since both $\sigma_X\otimes \sigma_X$ and $\sigma_Z\otimes \sigma_Z$ stabilize $\ket{\EPR}$.
1565	
1566	Finally, to establish consistency for the operators $P^A(a,0)$ where one
1567	coordinate is fixed to $0$, we exploit the exact Pauli braiding relation:
1568	\begin{align*}
1569	  P^A(a,0) \ket{\Psi} &=^{a,c,d} (-1)^{d \cdot c} P^A(a+c, d) P^A(c,
1570	                        d) \ket{\Psi} \\
1571	  \intertext{By approximate consistency of $P^A$,}
1572	  &\app{\eps^{1/8}}{a,c,d} (-1)^{d \cdot c}  P^A(a + c, d) X^A(c)
1573	    Z^A(d) \ket{\Psi} \\
1574	  \intertext{Applying property 1 (approximate consistency) twice,
1575	  first to $Z^A(d)$ and then to $X^A(c)$, we shift them to Bob's space:}
1576	  &\app{\sqrt{\eps}}{a,c,d} (-1)^{d \cdot c} Z^B(d) X^B(c) P^A(a+c, d)
1577	    \ket{\Psi} \\
1578	  \intertext{Now we apply approximate consistency of $P^A$ again:}
1579	  &\app{\eps^{1/8}}{a,c,d}  Z^B(d) X^B(c) X^A(a+c) Z^A(d) \ket{\Psi} \\
1580	  \intertext{Applying property 3 (approximate anticommutation) to
1581	  $X^A(a+c)$ and $Z^A(d)$, and then property 1 (approximate
1582	  consistency) to $X^B(c)$, we get}
1583	  &\app{\eps^{1/8}}{a,c,d} (-1)^{a \cdot d} Z^B(d) Z^A(d) X^A(a+c)
1584	    X^A(c) \ket{\Psi} \\
1585	  \intertext{We use property 2 (approximate linearity) to combine
1586	  $X^A(a+c)$ and $X^A(c)$:}
1587	  &\app{\eps^{1/4}}{a,c,d}  (-1)^{a \cdot d} Z^B(d) Z^A(d) X^A(a) \ket{\Psi}
1588	  \\
1589	  \intertext{Now, applying property 3 (approximate anticommutation),
1590	  we get,}
1591	  &\app{\eps^{1/8}}{a,c,d} Z^B(d) X^A(a) Z^A(d)  \ket{\Psi}.
1592	  \intertext{Finally, use property 1 (approximate consistency), and
1593	    the fact that $Z^A(d)$ is an observable to get}
1594	  &\app{\sqrt{\eps}}{a,c,d} X^A(a) Z^A(d) Z^A(d) \ket{\Psi} \\
1595	  &=^{a,c,d} X^A(a) \ket{\Psi}.
1596	\end{align*}
1597	\end{enumerate}
1598	
1599	\end{proof}
