1778	\subsection{Analysis of the energy test}
1779	\label{sec:energytest}
1780	
1781	The goal of the energy  test is to estimate the energy of a randomly
1782	chosen  term in the Hamiltonian. 
1783	
1784	\begin{lemma}
1785	Given a Hamiltonian $H$ as in~\eqref{eq:h-form}, the acceptance probability of the energy test, when the correct Pauli operators are applied by each player on its respective register of the $(rn)$-qubit encoding of an $n$-qubit state $\ket{\psi}$, is
1786	\begin{align*}
1787	\omega^*_{\energy}(H,\ket{\psi}) &= 1-\Big( \frac{1}{2m} \sum_{\ell = 1}^{m} \frac{ |\alpha_{\ell} | +
1788	  \alpha_{\ell} \langle \psi|H_\ell |\psi \rangle}{2} \Big)\\
1789	  &= 1-\Big(\frac{1}{4}\bra{\psi} H\ket{\psi} + \frac{1}{2m }
1790	    \sum_{\ell} |\alpha_{\ell}|\Big),
1791	\end{align*}
1792	where $H_\ell = \sigma_X(a_\ell)\sigma_Z(b_\ell)$ is the $\ell$-th term in the Hamiltonian.
1793	\label{lem:energy_test}
1794	\end{lemma}
1795	
1796	\begin{proof}
1797	The proof is a simple calculation in all points similar to that performed in~\cite[Section~4]{ji2015classical}; see in particular the discussion that precedes Theorem~23 in that paper. We omit the details.
1798	\end{proof}
1799	
1800	\subsection{Analysis of the consistency test}
1801	\label{sec:consistencytest}
1802	
1803	The goal of the energy consistency test is to guarantee that operators used by the special player on $XZ$-type queries are consistent with those used on other types of queries. 
1804	
1805	\begin{lemma}
1806	  Suppose the strategy $(N,\ket{\psi})$ for the players succeeds in the energy consistency test and the Pauli braiding test with probability $1 -
1807	  \eps_{}$ each. Then 
1808	  \[\frac{1}{m}\sum_{\ell=1}^m \big
1809		\| (\sp_\ell - \hat{X}(a)\hat{Z}(b))\ket{\psi}\big\|^2 \,=\,
1810	  O\big(\eps_{}^{1/32}\big), \]
1811	where $a$ and $b$ are strings such that $H_\ell = \sigma_X(a)\sigma_Z(b)$, and $\sp_\ell$ is the observable applied by the special player upon receiving the query $(XZ, a,  b)$ in the energy test. 
1812	 
1813	Moreover, the honest strategy succeeds in the test with probability $1$. 
1814	\label{lem:energy_consistency}
1815	\end{lemma}
1816	
1817	\begin{proof}
1818	We show that $XZ$-queries, $X$-queries, and $Z$-queries
1819	  on the special player are all consistent with $\overline{(X, c, c + a)}$ and
1820	  $\overline{(Z, c, c+b)}$  queries to the composite player. The analysis uses similar techniques to the analysis of the linearity test. First, let us
1821	  analyze the case when the verifier chooses $W=X$. Let the POVM applied by the composite player
1822	  be $\{\overline{M}_{c, c+a}^{\alpha \alpha'}\}$ and define marginalized
1823	  operators 
1824	  \[    \overline{M}_{c | c, c+a}^{\alpha} = \sum_{\alpha'} \overline{M}_{c,
1825	    c+a}^{\alpha\alpha'}.\]
1826	Likewise, let the POVM applied by the special player be
1827	$\hat{P}_{\ell}^{\alpha \alpha'}$ and define marginalized operators for the special player: 
1828	\[ \sp^{\alpha}_{a|\ell} = \sum_{\alpha'} \hat{P}^{\alpha \alpha'}_{\ell},
1829	\qquad \sp^{\alpha'}_{b | \ell} = \sum_{\alpha} \hat{P}^{\alpha
1830	  \alpha'}_{\ell}. \]
1831	The observable $\sp_\ell$ corresponding to the product of the special player's
1832	measurement outcomes is defined as
1833	\[ \sp_\ell = \sum_{\alpha \alpha'} (-1)^{\alpha \cdot \alpha'}
1834	\hat{P}^{\alpha \alpha'}_{\ell}. \]
1835	Recall that the Pauli braiding test (\thmref{isotwoplayer})
1836	guarantees the existence of operators $P^A(a,b)$ exactly satisfying
1837	the Pauli relations; let
1838	\[ \Xlin(a) := P^A(s, 0)\qquad\text{and}\qquad \Zlin(b) := P^A(0, b). \]
1839	Item (a) of \thmref{isotwoplayer} guarantees that $\Xlin(a)$ (resp. $\Zlin(b)$) is within $O(\eps_{}^{1/8})$ of 
1840	$\sx(a)$ (resp. $\sz(b)$), in the state-dependent distance $\Drho$. Associated with the observable $\Xlin(a)$ are the projectors
1841	$\Xlin^\alpha(a), \alpha \in \{\pm 1\}$, and likewise $\Zlin^\beta(b)$
1842	for $\Zlin(b)$.
1843	
1844	The following relations follow from the
1845	assumption that the players succeed with probability $1-\eps_{}$
1846	in the energy consistency test. We use the notation $\E_{\ell, a \sim
1847	  H_\ell}$ to indicate that the index $\ell$ is chosen uniformly at
1848	random, and then the string $a$ is chosen from the distribution of queries induced
1849	by the Hamiltonian term $H_\ell$; in contrast to $\E_a$ which indicates a uniformly
1850	random string. 
1851		  \begin{align}
1852	      \E_{\ell, a \sim H_\ell} \E_{c} \CON_\rho(\overline{M}_{c | c, c+a}^\alpha, \sx^\alpha(c)) &= 1 -  O(\eps_{}), \label{eq:energy_cons1}\\
1853	      \E_{\ell, a \sim H_\ell} \E_{c} \CON_\rho(\overline{M}_{c+a | c, c+a}^\alpha, \sx^\alpha(c + a)) &= 1 -   O(\eps_{}), \label{eq:energy_cons2}\\
1854	      \E_{\ell, a \sim H_\ell} \E_c \CON_\rho\Big(\sp_{a | \ell}^{\alpha}, \sum_{\beta \cdot \beta' =
1855	      \alpha}M_{c, c+a}^{\beta \beta'}\Big) &= 1- O(\eps_{}) \label{eq:energy_cons3}.
1856	  \end{align}
1857	  We use these relations to show that the special player's
1858	  marginalized measurement $\sp^{\alpha}_{a|\ell}$ is close to
1859	  $\Xlin^{\alpha}(a)$. We show
1860	  this in two steps. First, we relate the special player's measurement
1861	  $\sp^{\alpha}_{a|\ell}$ to the composite player's measurement:
1862	  \begin{align*}
1863	    \E_{\ell, a \sim H_\ell} \CON_\rho\big(\sp_{a|\ell}^{\alpha}, \Xlin^{\alpha}(a) \big) 
1864			&\geq     \E_{\ell, a \sim H_\ell}   \E_c \Big[ \CON_\rho\Big(\sum_{\beta \cdot \beta' = \alpha} \overline{M}^{\beta \beta'}_{c, c + \alpha}, \Xlin^\alpha(a) \Big)  - \Drho \Big(\sp^\alpha_{a | \ell}, \sum_{\beta \cdot \beta' = \alpha} \overline{M}^{\beta \beta'}_{c, c+ a}\Big) \Big] \\
1865	    &\geq \E_{\ell, a \sim H_\ell} \E_c   \CON_\rho\Big(\sum_{\beta \cdot \beta' = \alpha} \overline{M}^{\beta \beta'}_{c, c + a}, \Xlin^\alpha(a)\Big) - O(\sqrt{\eps_{}}), 
1866	%    &= \E_{\ell, a\sim H_\ell} \E_c \sum_{\alpha} \sum_{\beta \cdot \beta' = \alpha} \bavg{M^{\beta \beta'}_{c, c+a} \Xlin^\alpha(a)}{\Psi} - O(\sqrt{\eps_{\cons}}).
1867	\end{align*}
1868	where the first inequality follows from Lemma~\ref{lem:approx} and the
1869	second from \myeqref{condist} and~\eqref{eq:energy_cons3}.  Next we relate
1870	$M$ to a product of two measurements $\sx$:
1871	\begin{align*}
1872	    \E_{\ell, a \sim H_\ell} \CON_\rho\big(\sp_{a|\ell}^{\alpha},
1873	  \Xlin^{\alpha}(a) \big)  &\geq \E_{\ell, a\sim H_\ell} \E_c \CON_\rho\Big( \sum_{\beta \cdot \beta' = \alpha} \overline{M}^{\beta}_{c| c, c+a} \overline{M}^{\beta'}_{c+a|c, c+ a}, \Xlin^\alpha(a)\Big)  - O(\sqrt{\eps_{}})\\
1874	  &\geq \E_{\ell, a\sim H_\ell} \E_c \CON_\rho\Big(\sum_{\beta \cdot \beta' = \alpha} \sx^{\beta}(c) \sx^{\beta'}(c+a) \Xlin^\alpha(a)\Big) - O(\sqrt{\eps_{}}),
1875	\end{align*}
1876	as follows from~\eqref{eq:energy_cons2},~\eqref{eq:energy_cons1} and Lemmas~\ref{lem:approx} and~\myeqref{condist}.  Finally, we use the Pauli braiding test to relate
1877	$\sx$ to the exactly linear observable $\Xlin$. Starting from the above and using \lemref{consistency} to switch $\sx(c)$ to $\cx(c)$,
1878	\begin{align*}
1879	  \E_{\ell, a \sim H_\ell} \CON_\rho\Big(\sp_{a|\ell}^{\alpha}, \Xlin^{\alpha}(a) \Big) 
1880	                     \geq \E_{\ell, a\sim H_\ell} \E_c \CON_\rho\Big(
1881	                       \sum_{\beta \cdot \beta' = \alpha}
1882	                       \cx^{\beta}(c) \sx^{\beta'}(c+a),
1883	                       \Xlin^\alpha(a)\Big)
1884	                        - O(\sqrt{\eps_{}}).
1885													\end{align*}
1886	 Next, we use \thmref{isotwoplayer} and \lemref{approx} to sequentially exchange the remaining $\sx$, then $\overline{X}$, to $\Xlin$, to obtain 
1887	\begin{align}
1888	   \E_{\ell, a \sim H_\ell} \CON_\rho\Big(\sp_{a|\ell}^{\alpha}, \Xlin^{\alpha}(a) \Big) 
1889		\geq \E_{\ell, a\sim H_\ell} \E_c  \CON_\rho\Big( \sum_{\beta \cdot \beta' = \alpha} \Xlin^{\beta}(c) \Xlin^{\beta'}(c+a) ,\Xlin^\alpha(a)\Big)  - O({\eps}^{1/16}). \label{eq:energytox}
1890		\end{align}
1891	Finally, the product of the three $\Xlin$ operators can be eliminated using the exact linearity relations. Performing an analogous analysis for the $Z$ operators,
1892	  \begin{equation} \E_{\ell, b \sim H_\ell} \CON_\rho(\sp_{b|\ell}^{\beta}, \Zlin(b)^\beta) \geq 1 - O(\eps_{}^{1/16}). \label{eq:energytoz} \end{equation}
