1894	  \begin{alignat*}{2}
1895	     \sp_\ell \ket{\psi} &=^{\ell} \sp_{a|\ell} \sp_{b|\ell} \ket{\psi} \\
1896	    &\app{\eps^{1/32}}{\ell}  \sp_{a|\ell} \Zlin(b) \ket{\psi} \qquad &\text{by \myeqref{energytoz}, \lemref{approx}, and \myeqref{condist}}\\
1897	    &=^{\ell}\E_c \sp_{a|\ell} \Zlin(b + c) \Zlin(c) \ket{\psi} \qquad &\text{by exact linearity} \\
1898	    &\app{\eps^{1/16}}{\ell} \E_c \cz(c) \cz(b+c) \sp_{a|\ell} \ket{\psi} \qquad &\text{by \thmref{isotwoplayer} and \lemref{consistency}}\\
1899	    &\app{\eps^{1/32}}{\ell} \E_c \cz(c)\cz(b+c) \Xlin(a) \ket{\psi} \qquad &\text{by \myeqref{energytox} and \lemref{approx}}\\
1900	    &\app{\eps^{1/16}}{\ell} \E_c \Xlin(a) \Zlin(b+c)\Zlin(c) \ket{\psi} \qquad &\text{by \thmref{isotwoplayer} and \lemref{consistency}}\\
1901	    &=^{\ell} \Xlin(a) \Zlin(b) \ket{\psi} \qquad &\text{by exact linearity.}
1902	  \end{alignat*}
1903	\end{proof}
